tent:space-between;gap:12px}.material-picker{border-top:1px solid #decba9}.material-picker article{display:flex;align-items:center;gap:12px;flex-wrap:wrap;padding:13px 0;border-bottom:1px solid #decba9}.material-picker .selected-fixed-version{display:flex;align-items:center;gap:12px;width:100%;padding-left:30px;font-size:13px;color:#765f40}.material-picker .selected-fixed-version label{display:flex;align-items:center;gap:8px}.material-picker label{flex:1;display:flex;grid-template-columns:auto 1fr;align-items:flex-start;gap:10px;cursor:pointer}.material-picker input,.authorization input{width:19px;min-height:19px;margin-top:2px;accent-color:#8a402b}.material-picker small,.hall-result-item small{display:block;margin-top:3px;color:#765f40;overflow-wrap:anywhere}.draft-preview{max-height:320px;overflow:auto;white-space:pre-wrap;background:#fffdf8;border:1px solid #d3c5aa;padding:22px;line-height:1.8}.draft-preview-image{display:block;max-width:100%;max-height:360px;margin:auto;object-fit:contain;border:1px solid #d3c5aa}.confirmation-grid{margin:0;border-top:1px solid #decba9}.confirmation-grid>div{display:grid;grid-template-columns:100px minmax(0,1fr);gap:18px;padding:13px 0;border-bottom:1px solid #decba9}.confirmation-grid dt{color:#765f40;font-size:13px}.confirmation-grid dd{margin:0;overflow-wrap:anywhere;line-height:1.55}.authorization{display:flex!important;grid-template-columns:auto 1fr;align-items:flex-start;gap:10px!important;padding:10px 0}.case-receipt{padding-bottom:12px;border-bottom:1px solid #decba9}.case-receipt p{margin:5px 0 0;color:#765f40;font-size:13px}.case-tabs{display:flex;gap:14px;border-bottom:1px solid #decba9}.case-tabs button{min-height:38px;padding:7px 4px;border:0;border-radius:0;background:transparent;border-bottom:2px solid transparent}.case-tabs button[aria-pressed=true]{color:#8a402b;border-bottom-color:#8a402b}.case-body{display:grid;gap:12px}.technical-details{font-size:12px;color:#765f40}.hall-result-item{display:grid;gap:5px;padding:12px 0;border-bottom:1px solid #decba9}.result-actions{display:flex;gap:8px;flex-wrap:wrap}.result-actions button{min-height:34px;padding:5px 10px;font-size:13px}@media(max-width:620px){.draft-strip,.case-receipt{align-items:flex-start;flex-direction:column}.draft-actions{justify-content:stretch}.draft-actions button{flex:1}.draft-actions>span:first-child{width:100%;margin-right:0}.confirmation-grid>div{grid-template-columns:68px minmax(0,1fr);gap:12px}.material-picker article{align-items:flex-start;flex-direction:column}.material-picker article>button{align-self:flex-end}}@media(max-height:500px) and (min-width:621px){.hall-draft-editor{gap:10px;padding-bottom:8px}.draft-intro{margin-bottom:0}.hall-draft-editor form{gap:10px}.hall-draft-editor textarea{min-height:72px}.draft-strip{padding:10px 0}.draft-actions{padding-top:10px;margin-top:0}.case-receipt{padding-bottom:8px}}
